/* neutron headless test: DXIL (Shader Model 6) hull and domain shaders on D3D12 through DXMT, run
 * as a Metal mesh pipeline like the DXBC ones (tests/d3d12_tess.c, same cases: tri and quad
 * domains, patch constants, a displaced edge that only shows when the patch is tessellated,
 * indexed and instanced patches). The quad patch constant function also reads an output
 * control point. Exit code 0 = all pixels match (needs DXMT_CONFIG="d3d12.shaderModel = 66").
 *
 *   cbuffer HsCb : register(b0) { float4 tint; };
 *   cbuffer HsConst : register(b1) { float factor; float3 pad1; };
 *   cbuffer DsConst : register(b2) { float bend; float3 pad2; };
 *   struct VIn { float2 pos : POSITION; float4 col : COLOR; };
 *   struct CP { float4 pos : POS; float4 col : COLOR; };
 *   CP vs(VIn i, uint inst : SV_InstanceID) {
 *     CP o; o.pos = float4(i.pos + float2(1.0 * inst, 0), 0, 1); o.col = i.col; return o; }
 *
 *   struct TriPC { float e[3] : SV_TessFactor; float i : SV_InsideTessFactor; float4 tint : TINT; };
 *   TriPC tri_pc(InputPatch<CP, 3> p) { TriPC o; o.e[0] = o.e[1] = o.e[2] = 4; o.i = 4; o.tint = tint; return o; }
 *   [domain("tri")] [partitioning("integer")] [outputtopology("triangle_cw")] [outputcontrolpoints(3)]
 *   [patchconstantfunc("tri_pc")] CP tri_hs(InputPatch<CP, 3> p, uint i : SV_OutputControlPointID) { return p[i]; }
 *   struct DSOut { float4 pos : SV_Position; float4 col : COLOR; };
 *   [domain("tri")] DSOut tri_ds(TriPC pc, float3 uvw : SV_DomainLocation, const OutputPatch<CP, 3> p) {
 *     DSOut o; o.pos = p[0].pos * uvw.x + p[1].pos * uvw.y + p[2].pos * uvw.z;
 *     o.col = float4(uvw, 1) * pc.tint; return o; }
 *
 *   struct QuadPC { float e[4] : SV_TessFactor; float i[2] : SV_InsideTessFactor; };
 *   QuadPC quad_pc(InputPatch<CP, 4> p, const OutputPatch<CP, 4> op) { QuadPC o; o.e[0] = o.e[1] = o.e[2] = o.e[3] = factor;
 *     o.i[0] = o.i[1] = factor * op[3].col.a; return o; }
 *   [domain("quad")] [partitioning("integer")] [outputtopology("triangle_cw")] [outputcontrolpoints(4)]
 *   [patchconstantfunc("quad_pc")] CP quad_hs(InputPatch<CP, 4> p, uint i : SV_OutputControlPointID) { return p[i]; }
 *   [domain("quad")] DSOut quad_ds(QuadPC pc, float2 uv : SV_DomainLocation, const OutputPatch<CP, 4> p) {
 *     DSOut o; float4 top = lerp(p[0].pos, p[1].pos, uv.x), bottom = lerp(p[2].pos, p[3].pos, uv.x);
 *     o.pos = lerp(top, bottom, uv.y);
 *     o.pos.y += bend * sin(3.14159265 * uv.x) * (1 - uv.y);
 *     o.col = p[0].col; return o; }
 *   float4 ps(DSOut i) : SV_Target { return i.col; }
 *
 * dxc 1.9.2609: -T vs_6_0 -E vs, -T hs_6_0 -E tri_hs / quad_hs, -T ds_6_0 -E tri_ds / quad_ds,
 * -T ps_6_0 -E ps
 * Build: x86_64-w64-mingw32-clang -O2 -o d3d12_dxil_tess.exe d3d12_dxil_tess.c -ld3d12
 */
